(()=>{'use strict';const $=id=>document.getElementById(id),key='zuxuru-designer-work-v1',areas=[['sales','Sales & customers','prospects'],['marketing','Marketing & social','my-studio'],['branding','Brand identity','designer'],['visibility','Visibility & SEO','evidence'],['products','Product discovery','catalogue'],['opportunities','Opportunities & gaps','my-work'],['skills','AI skills','my-studio'],['career','Career & rebuilding','my-work']];let s={tasks:[],studio:[]};function valid(v){return v&&['tasks','studio'].every(k=>Array.isArray(v[k])&&v[k].length<=500&&v[k].every(r=>r&&typeof r.id==='string'&&typeof r.title==='string'));}try{const v=JSON.parse(localStorage.getItem(key));if(valid(v))s=v;}catch{}const el=(t,text)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;return n;};function safe(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}function save(){try{localStorage.setItem(key,JSON.stringify(s));$('designer-work-status').textContent='Saved in this browser.';}catch{$('designer-work-status').textContent='Could not save. Export a backup.';}}
areas.forEach(([id,name,target],i)=>{for(const select of ['designer-work-filter','designer-task-area'])$(select).append(new Option(name,id));const card=el('article');const link=el('a',String(i+1).padStart(2,'0')+' / '+name);link.href='#my-work';link.onclick=()=>{$('designer-work-filter').value=id;render();};const open=el('a','Open tools');open.href='#'+target;open.style.display='block';open.style.marginTop='14px';card.className='record';card.append(link,open);$('designer-work-areas').append(card);});

async function openTaskStudio(task){
 const jobId=task.sourceStudioJobId||'task-'+task.id;
 const get=async()=>{const r=await fetch('/api/studio/jobs?archived=1&selected='+encodeURIComponent(jobId));const d=await r.json();if(!r.ok)throw Error(d.error||'Studio queue unavailable.');return d.jobs.find(j=>j.id===jobId);};
 let job=await get();
 if(!job){if(task.sourceStudioJobId)throw Error('The original Studio job is unavailable. No other job was opened.');if(!window.designerCloudReady?.())throw Error('Wait for Cloud saved before sending this task to Studio.');const r=await fetch('/api/studio/jobs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'route'})});const d=await r.json();if(!r.ok)throw Error(d.error);job=await get();if(!job)throw Error('This task was not routed. Only open marketing and branding tasks can create a Studio job.');}
 const frame=$('studio-dashboard-frame');if(!frame)throw Error('Open Creative Studio from the dashboard navigation.');
 location.hash='digital-studio';
 const deadline=Date.now()+15000;
 while(typeof frame.contentWindow?.openStudioJob!=='function'){if(Date.now()>deadline)throw Error('Studio is still loading. Try Open in Studio again.');await new Promise(resolve=>setTimeout(resolve,200));}
 await frame.contentWindow.openStudioJob(jobId);
 $('designer-work-status').textContent='Opened your saved Studio job: '+job.title;
}
function render(){const tasks=$('designer-task-list');tasks.replaceChildren();const shown=window.bongaTaskAgenda(s.tasks,$('designer-work-filter').value,$('designer-task-view').value);$('designer-agenda-summary').textContent=shown.length+' tasks shown · '+s.tasks.filter(t=>!t.done).length+' open in all work areas · '+s.tasks.filter(t=>t.done).length+' completed · '+Math.max(0,500-s.tasks.length)+' queue slots available. Dated work is shown first.';if(!shown.length)tasks.append(el('p','No tasks match this area and view. Change the filters or add a task.'));shown.forEach(t=>{const card=el('article');card.className='record';const label=el('label'),check=el('input');check.type='checkbox';check.checked=t.done;check.onchange=()=>{if(check.checked){const note=prompt('What did you complete? Add the actual result or deliverable.',t.progressNote||'');if(!note?.trim()){check.checked=!!t.done;return;}t.progressNote=note.trim().slice(0,3000);t.status='Completed';}else t.status='In progress';t.done=check.checked;t.progressUpdatedAt=new Date().toISOString();t.progressMethod='Owner-entered progress; result not independently verified';save();render();};label.append(check,document.createTextNode(t.title));card.append(label,el('p',t.deliverable),el('p','Due: '+(t.due||'Not set')),el('p','Progress: '+(t.done?'Completed':t.status||'Proposed')));if(t.progressNote)card.append(el('p',t.progressNote));const progress=el('details'),summary=el('summary','Update progress'),select=el('select');select.setAttribute('aria-label','Task progress for '+t.title);['Proposed','In progress','Review','Completed'].forEach(status=>{const option=el('option',status);option.value=status;select.append(option);});select.value=t.done?'Completed':['Proposed','In progress','Review'].includes(t.status)?t.status:'Proposed';const note=el('textarea');note.value=t.progressNote||'';note.maxLength=3000;note.placeholder='Actual result, deliverable or next step';note.setAttribute('aria-label','Result note for '+t.title);const dueLabel=el('label','Task due date'),dueInput=el('input');dueInput.type='date';dueInput.value=t.due||'';dueLabel.append(dueInput);const update=el('button','Save progress');update.type='button';update.onclick=()=>{if(['Review','Completed'].includes(select.value)&&!note.value.trim()){alert('Add the actual deliverable or result before review or completion.');note.focus();return;}Object.assign(t,{due:dueInput.value,status:select.value,done:select.value==='Completed',progressNote:note.value.trim(),progressUpdatedAt:new Date().toISOString(),progressMethod:'Owner-entered progress; result not independently verified'});save();render();};progress.append(summary,select,dueLabel,note,update);card.append(progress);if(t.sourceOrderId){const order=el('button','Open source customer order');order.type='button';order.onclick=()=>document.dispatchEvent(new CustomEvent('fashion-open-order',{detail:{id:t.sourceOrderId}}));card.append(order);}if(t.sourceStudioJobId||['marketing','branding'].includes(t.area)){const studio=el('button','Open in Studio');studio.type='button';studio.onclick=async()=>{studio.disabled=true;try{await openTaskStudio(t);}catch(e){$('designer-work-status').textContent=e.message||'Studio could not open.';}finally{studio.disabled=false;}};card.append(studio);} const remove=el('button','Remove task');remove.onclick=()=>{s.tasks=s.tasks.filter(x=>x.id!==t.id);save();render();};card.append(remove);tasks.append(card);});const box=$('designer-studio-records');box.replaceChildren();s.studio.forEach(r=>{const card=el('article');card.className='record';card.append(el('h3',r.title),el('p',r.type+' · '+r.stage),el('p',r.notes));const u=safe(r.url);if(u){const a=el('a','Open actual asset');a.href=u;a.target='_blank';a.rel='noopener noreferrer';card.append(a);}const remove=el('button','Remove project');remove.onclick=()=>{if(confirm('Remove this creative project?')){s.studio=s.studio.filter(x=>x.id!==r.id);save();render();}};card.append(remove);box.append(card);});}
document.addEventListener('fashion-review-followup',event=>{let base;try{base=JSON.parse(localStorage.getItem('zuxuru-fashion-service-v1'))||{};}catch{base={};}const order=(base.orders||[]).find(o=>o.id===event.detail?.id);if(!order){$('designer-work-status').textContent='This customer enquiry is no longer saved.';return;}if(s.tasks.some(t=>!t.done&&t.sourceOrderId===order.id)){$('designer-work-status').textContent='An open task already links to this customer. Review your sales tasks before adding another.';$('designer-work-filter').value='sales';render();location.hash='my-work';return;}const form=$('designer-task-form');if(['title','deliverable','due'].some(k=>form.elements.namedItem(k).value)&&!confirm('Replace your unsaved task brief?'))return;form.dataset.sourceOrderId=order.id;form.elements.namedItem('area').value='sales';form.elements.namedItem('title').value=('Follow up with '+String(order.customer||'customer')).slice(0,200);form.elements.namedItem('deliverable').value=('Review the enquiry at '+String(order.stage||'Enquiry')+'. '+String(order.next||'Agree the next customer action.')+'\n\nReviewed message draft:\n'+String(event.detail?.message||'')).slice(0,1000);form.elements.namedItem('due').value='';location.hash='my-work';form.scrollIntoView({behavior:'auto'});form.elements.namedItem('due').focus();$('designer-work-status').textContent='Choose a follow-up date, review the brief and Add to my work. No message has been sent.';});$('designer-task-form').addEventListener('reset',()=>{delete $('designer-task-form').dataset.sourceOrderId;});
$('designer-task-form').onsubmit=e=>{e.preventDefault();if(s.tasks.length>=500){$('designer-work-status').textContent='Your 500-task queue is full. Export your work and remove records you no longer need before adding a task.';return;}const source=e.target.dataset.sourceOrderId;if(source){let base;try{base=JSON.parse(localStorage.getItem('zuxuru-fashion-service-v1'))||{};}catch{base={};}if(!(base.orders||[]).some(o=>o.id===source)){$('designer-work-status').textContent='The source enquiry was removed. Refresh this brief before saving.';return;}}s.tasks.push({...Object.fromEntries(new FormData(e.target)),...(source?{sourceOrderId:source}:{}),id:crypto.randomUUID(),done:false});save();e.target.reset();render();};$('designer-studio-form').onsubmit=e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.url=safe(r.url);s.studio.push({...r,id:crypto.randomUUID()});save();e.target.reset();render();};$('designer-work-filter').onchange=render;$('designer-task-view').onchange=render;
$('designer-review').onclick=async()=>{const button=$('designer-review');button.disabled=true;let release;try{release=window.bongaRunGate.begin();const response=await fetch('/api/designer/review',{method:'POST'});const result=await response.json();if(!response.ok)throw Error(result.error);const newTasks=(result.tasks||[]).filter(t=>!s.tasks.some(x=>!x.done&&(x.id===t.id||x.title===t.title)));if(s.tasks.length+newTasks.length>500)throw Error('Review needs '+newTasks.length+' task slots. Export your work and remove records you no longer need first.');let added=0;for(const t of newTasks){if(!s.tasks.some(x=>!x.done&&(x.id===t.id||x.title===t.title))){s.tasks.push(t);added++;}}if(added)save();render();$('designer-review-note').textContent=added+' next-action tasks added. '+result.notice;}catch(e){$('designer-review-note').textContent=e.message||'Business review unavailable.';}finally{release?.();button.disabled=false;}};
$('designer-work-export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({format:key,...s},null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='zuxuru-designer-work.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('designer-work-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const v=JSON.parse(await f.text());if(v.format!==key||!valid(v))throw Error();if(!confirm('Replace daily work and creative projects with this backup?'))return;s={tasks:v.tasks,studio:v.studio};save();render();}catch{$('designer-work-status').textContent='Invalid backup. No records restored.';}e.target.value='';};render();})();
